    if fitting_bins_count == 1 && post_residual >= next_item_size {
        score -= (next_item_size - post_residual) as f64 * 8.0;
    }

    // Penalize creating too many open bins
    score += (open_bins_count as f64 / total_items as f64) * 3.5;

    // Reward bins with a better-than-average residual space
    if post_residual > mean_residual {
        score -= (post_residual - mean_residual) as f64 * 1.2;
    }

    // Penalize bins that have a high percentage of remaining capacity
    let high_capacity_usage = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
